/**
 * Imports narration clips generated by hand on elevenlabs.io (one clip per cue).
 *
 *   npm run voiceover:import -- <folder-with-clips>
 *
 * Matching:
 *   - Files whose names contain c01 … c31 are matched by that number.
 *   - Otherwise, if the folder holds exactly one file per cue, files are matched in
 *     name order. ElevenLabs downloads are timestamped, so generating the lines in
 *     order c01 → c31 makes name order correct. The mapping is printed so you can check it.
 *
 * Each clip has leading/trailing silence trimmed so the timeline stays tight, is
 * re-encoded to public/voiceover/<cue>.mp3, and its real duration goes into the
 * manifest. Manual clips have no word timestamps, so words are spread evenly
 * across each clip's real duration.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { CUES } from "../src/script.ts";

const ROOT = path.resolve(import.meta.dirname, "..");
const OUT_DIR = path.join(ROOT, "public", "voiceover");
const MANIFEST_PATH = path.join(ROOT, "src", "voiceover", "manifest.json");
const AUDIO = /\.(mp3|wav|m4a|ogg|flac|aac)$/i;

const dir = process.argv[2];
if (!dir) {
  console.error("Usage: npm run voiceover:import -- <folder-with-clips>");
  process.exit(1);
}

const files = readdirSync(dir)
  .filter((f) => AUDIO.test(f))
  .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

const byId = new Map<string, string>();
for (const f of files) {
  const m = f.match(/(?:^|[^a-z0-9])c(\d{1,2})(?:[^0-9]|$)/i) ?? f.match(/^c(\d{1,2})/i);
  if (m) byId.set(`c${m[1].padStart(2, "0")}`, f);
}

let mapping: [string, string][];
if (CUES.every((c) => byId.has(c.id))) {
  mapping = CUES.map((c) => [c.id, byId.get(c.id)!]);
} else if (files.length === CUES.length) {
  console.log("Files are not named c01…c31, so they are matched in name order:\n");
  mapping = CUES.map((c, i) => [c.id, files[i]]);
} else {
  const missing = CUES.filter((c) => !byId.has(c.id)).map((c) => c.id);
  console.error(
    `Found ${files.length} audio files, expected ${CUES.length}.\n` +
      (byId.size ? `Missing cues: ${missing.join(", ")}\n` : "") +
      "Name the files c01.mp3 … c31.mp3, or provide exactly one file per cue in order.",
  );
  process.exit(1);
}

const ffmpeg = (args: string[]) => execFileSync("ffmpeg", ["-y", "-loglevel", "error", ...args]);
const probe = (file: string) =>
  parseFloat(
    execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", file], {
      encoding: "utf8",
    }).trim(),
  );

mkdirSync(OUT_DIR, { recursive: true });
const cues: Record<string, { file: string; duration: number; hash: string; words: never[] }> = {};

// Trim silence at both ends (via reverse), keep 60ms of air, normalise to 44.1k mono-safe MP3.
const TRIM =
  "silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.06," +
  "areverse,silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.06,areverse";

for (const [id, f] of mapping) {
  const src = path.join(dir, f);
  const file = `voiceover/${id}.mp3`;
  const dest = path.join(ROOT, "public", file);
  ffmpeg(["-i", src, "-af", TRIM, "-ar", "44100", "-codec:a", "libmp3lame", "-b:a", "192k", dest]);
  const duration = probe(dest);
  cues[id] = { file, duration: +duration.toFixed(3), hash: "manual", words: [] };
  const text = CUES.find((c) => c.id === id)!.text;
  console.log(`✓ ${id}  ${duration.toFixed(2).padStart(5)}s  ${f}\n      “${text}”`);
}

writeFileSync(MANIFEST_PATH, JSON.stringify({ generated: true, source: "manual", cues }, null, 2) + "\n");
const total = Object.values(cues).reduce((s, c) => s + c.duration, 0);
console.log(`\nWrote ${path.relative(ROOT, MANIFEST_PATH)} · spoken audio ${total.toFixed(1)}s`);
